define("mod_seledascorm/reporting_dashboard", [], function() {// Progressive enhancement: all figures remain readable without JavaScript.
const init = () => {
    const sidebar = document.querySelector('.sd-catalogue details');
    if (sidebar && matchMedia('(max-width:700px)').matches) sidebar.open = false;
    const chart = document.getElementById('sd-block-bars');
    if (!chart) {
        return;
    }
    chart.addEventListener('click', event => {
        const row = event.target.closest('li');
        if (row && !event.target.closest('a')) row.querySelector('a')?.click();
    });
    const donut = document.querySelector('.sd-donut:not(.is-empty)');
    donut?.addEventListener('click', event => {
        const box = donut.getBoundingClientRect();
        const angle = (Math.atan2(event.clientY - box.top - box.height / 2,
            event.clientX - box.left - box.width / 2) * 180 / Math.PI + 450) % 360 / 3.6;
        const style = getComputedStyle(donut);
        const index = angle < parseFloat(style.getPropertyValue('--done')) ? 0 :
            angle < parseFloat(style.getPropertyValue('--progress')) ? 1 : 2;
        document.querySelectorAll('.sd-legend a')[index]?.click();
    });
    const duration = ms => {
        const seconds = Math.floor(ms / 1000);
        return [Math.floor(seconds / 3600), Math.floor(seconds / 60) % 60, seconds % 60]
            .map(part => String(part).padStart(2, '0')).join(':');
    };
    document.querySelectorAll('[data-sd-measure]').forEach(button => {
        button.addEventListener('click', () => {
            const measure = button.dataset.sdMeasure;
            const rows = [...chart.children].sort((a, b) => Number(b.dataset[measure]) - Number(a.dataset[measure]));
            const maximum = Math.max(1, ...rows.map(row => Number(row.dataset[measure])));
            rows.forEach((row, index) => {
                const value = Number(row.dataset[measure]);
                row.hidden = index >= 8;
                row.querySelector('.sd-bar-value').textContent = measure === 'ms' ? duration(value) : value.toLocaleString();
                row.querySelector('.sd-bar-track span').style.width = (value / maximum * 100) + '%';
                chart.append(row);
            });
            document.querySelectorAll('[data-sd-measure]').forEach(item => {
                item.setAttribute('aria-pressed', String(item === button));
            });
        });
    });
};
return {init};});